bruteForceSolution.code:
function patternRightTriangle(n) {
  let rows = [];
  for (let i = 1; i <= n; i++) {
    let row = '';
    for (let j = 1; j <= i; j++) {
      row += '*';
    }
    rows.push(row);
  }
  return rows.join('\n');
}

